import sqlite3,random
c=sqlite3.connect('warehouse.db')
def rows(where):
    return c.execute(f"select searches,clicks from query_stats s join query_labels l on l.query_id=s.query_id where week='2026-W40' and l.intent='navigational' and {where}").fetchall()
for name,w in [('current','l.is_current=1'),('v1cur','l.is_current=1 and l.label_version=1'),('v2','l.label_version=2'),('v1all','l.label_version=1')]:
    r=rows(w);print(name,len(r),100*sum(x[1] for x in r)/sum(x[0] for x in r))
